// @vanguard/trust-engine Browser Verifier (< 5 KB dependency-free RFC 6962 + SHA-256 chain verifier)
(function(g){
"use strict";
const e=new TextEncoder(),h=b=>Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,"0")).join(""),
f=x=>{const b=new Uint8Array(x.length/2);for(let i=0;i<b.length;i++)b[i]=parseInt(x.substr(i*2,2),16);return b},
s=async b=>h(await crypto.subtle.digest("SHA-256",b)),
c=v=>{if(typeof v==="string")return JSON.stringify(v.normalize("NFC"));if(v===null||typeof v!=="object")return JSON.stringify(v);if(Array.isArray(v))return"["+v.map(c).join(",")+"]";const k=Object.keys(v).sort();return"{"+k.map(p=>JSON.stringify(p.normalize("NFC"))+":"+c(v[p])).join(",")+"}"},
n=async(p,l,r)=>{const L=f(l),R=f(r),o=new Uint8Array(1+L.length+R.length);o[0]=p;o.set(L,1);o.set(R,1+L.length);return s(o)};
async function verifyChain(recs){
  if(!Array.isArray(recs)||!recs.length)return{valid:false,reason:"empty",headHash:"0".repeat(64)};
  let p="0".repeat(64);
  for(let i=0;i<recs.length;i++){
    const r=recs[i];
    if(r.seq!==i+1||r.prevHash!==p)return{valid:false,reason:"continuity@"+(i+1),headHash:p};
    const d=await s(e.encode(c({seq:r.seq,kind:r.kind,at:r.at,actorId:r.actorId,summary:r.summary,payload:r.payload,prevHash:r.prevHash})));
    if(d!==r.hash)return{valid:false,reason:"hash@"+r.seq,headHash:p};
    p=d;
  }
  return{valid:true,entries:recs.length,headHash:p};
}
async function verifyInclusion(pr){
  if(!pr||pr.treeSize<=0||pr.leafIndex<0||pr.leafIndex>=pr.treeSize)return false;
  if(pr.treeSize===1)return Array.isArray(pr.auditPath)&&pr.auditPath.length===0&&pr.leafHash===pr.rootHash;
  let fn=pr.leafIndex,sn=pr.treeSize-1,r=pr.leafHash;
  for(const p of pr.auditPath){
    if(sn===0)return false;
    if((fn&1)===1||fn===sn){r=await n(1,p,r);while(fn!==0&&(fn&1)===0){fn>>=1;sn>>=1}}
    else r=await n(1,r,p);
    fn>>=1;sn>>=1;
  }
  return sn===0&&r===pr.rootHash;
}
async function hashLeaf(v){const u=e.encode(c(v)),o=new Uint8Array(1+u.length);o[0]=0;o.set(u,1);return s(o)}
async function verifyBundle(b){
  const ch=await verifyChain(b&&b.records?b.records:[]);
  const merkleOk=b&&b.inclusionProof?await verifyInclusion(b.inclusionProof):false;
  return{chainValid:ch.valid,chain:ch,merkleValid:merkleOk,verified:ch.valid&&merkleOk};
}
g.VanguardVerifier={canonicalJson:c,verifyChain,verifyInclusion,hashLeaf,verifyBundle,version:"1.0.0"};
})(typeof globalThis!=="undefined"?globalThis:window);
